            "source": "graph = None\nif GRAPH_AVAILABLE:\n    from research_agent.graph import build_graph\n    graph = build_graph(provider, tools)\n    print(graph.get_graph().draw_mermaid())\nelse:\n    print(\"Skipped: langgraph is not installed.\")"
